	@Test
	void trustedOriginStreamsWithAcceptAndMetadata() throws Exception {
		AtomicReference<String> accept = new AtomicReference<>();
		byte[] turtle = "<urn:s> <urn:p> <urn:o> .\n".getBytes(StandardCharsets.UTF_8);
		HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		server.createContext("/source.ttl", exchange -> {
			accept.set(exchange.getRequestHeaders().getFirst("Accept"));
			exchange.getResponseHeaders().add("Content-Type", "text/turtle; charset=utf-8");
			exchange.getResponseHeaders().add("Last-Modified", "Wed, 21 Oct 2015 07:28:00 GMT");
			exchange.sendResponseHeaders(200, turtle.length);
			try (var body = exchange.getResponseBody()) {
				body.write(turtle);
			}
		});
		server.start();
		try {
			URL source = url(server, "/source.ttl");
			ServerRemoteResourceOpener opener = new ServerRemoteResourceOpener(origin(server));
			try (RemoteResourceOpener.RemoteResource response = opener.open(source, List.of("text/turtle"), 0)) {
				assertThat(response.getFinalUrl()).isEqualTo(source);
				assertThat(response.getContentType()).isEqualTo("text/turtle; charset=utf-8");
				assertThat(response.getLastModified()).isEqualTo(Instant.parse("2015-10-21T07:28:00Z").toEpochMilli());
				assertThat(new String(response.getInputStream().readAllBytes(), StandardCharsets.UTF_8))
						.isEqualTo(new String(turtle, StandardCharsets.UTF_8));
			}
			assertThat(accept.get()).isEqualTo("text/turtle");
		} finally {
			server.stop(0);
		}
	}

